public class PointApp {
  static final int N = 10_000_000;

  static class Point {
    final int x;
    final int y;

    Point(int x, int y) {
      this.x = x;
      this.y = y;
    }

    double distance() {
      return Math.sqrt((double) x * x + (double) y * y);
    }
  }

  // Each iteration allocates a Point. If the JIT proves the Point
  // never escapes this loop (not stored, not passed elsewhere), it
  // can be scalar-replaced: x and y live in registers, no heap
  // allocation at all. If the loop handed points to a list instead,
  // every Point would hit Eden and eventually be GC'd.
  public static void main(String[] args) {
    double total = 0.0;
    for (int i = 0; i < N; i++) {
      Point p = new Point(i, i); // ❌ OLD: new Point(i,i) → Eden allocation each iteration
      total += p.distance();
    }
    System.out.println(total / N);
  }
}

