public class ScalarApp {
  static final int N = 10_000_000;

  // This is what the C2 JIT compiles the escaping loop into when
  // escape analysis + scalar replacement succeed: zero heap
  // allocations inside the loop, everything in registers.
  // Run with -XX:+PrintEliminateAllocations to observe the
  // eliminated allocations.
  public static void main(String[] args) {
    double total = 0.0;
    for (int i = 0; i < N; i++) {
      int px = i; // ✅ NEW: scalar-replaced — x,y in registers, zero heap allocations
      int py = i;
      total += Math.sqrt((double) px * px + (double) py * py);
    }
    System.out.println(total / N);
  }
}
